// ==========================================
// CONFIGURATION
// ==========================================
const CONFIG = {
  // The email address that will receive new lead notifications:
  RECIPIENT_EMAIL: 'zensoralabs@gmail.com',

  // Display name for outgoing notifications
  SENDER_NAME: 'Pixlark Marketing Leads',

  // Send an automatic confirmation email to the person who submitted the form?
  SEND_CLIENT_AUTO_REPLY: true,

  // Automatically save submissions into a Google Sheet
  SAVE_TO_SHEET: true,
  SHEET_NAME: 'Leads'
};

// Crystal-clear high-resolution PixlArk logo asset for 100% reliable Gmail & Outlook rendering
const LOGO_IMAGE_BASE64 = '';

function getInlineBrandImages() {
  return {
    logo_img: Utilities.newBlob(Utilities.base64Decode(LOGO_IMAGE_BASE64), 'image/png', 'logo.png')
  };
}

/**
 * Handle HTTP POST requests (from the Pixlark website contact form)
 */
function doPost(e) {
  try {
    let data = {};

    // 1. Parse incoming payload (JSON or Form URL encoded)
    if (e && e.postData && e.postData.contents) {
      try {
        data = JSON.parse(e.postData.contents);
      } catch (jsonErr) {
        data = e.parameter || {};
      }
    } else if (e && e.parameter) {
      data = e.parameter;
    }

    const fullName = (data.fullName || data.name || 'Anonymous Prospect').trim();
    const email = (data.email || '').trim();
    const phone = (data.phone || '').trim();
    const website = (data.website || '').trim();
    const service = (data.service || data.services || 'Not specified').trim();
    const industry = (data.industry || 'Not specified').trim();
    const region = (data.region || 'Not specified').trim();
    const goals = Array.isArray(data.goals) ? data.goals.join(', ') : (data.goals || 'Not specified');
    const currentMarketing = (data.currentMarketing || data.marketing || 'Not specified').trim();
    const budget = (data.budget || 'Not specified').trim();
    const message = (data.message || '').trim();
    const timestamp = new Date().toLocaleString('en-US', {
      timeZone: 'Asia/Kolkata',
      dateStyle: 'full',
      timeStyle: 'short'
    });

    // Basic validation
    if (!email) {
      return ContentService.createTextOutput(JSON.stringify({
        status: 'error',
        message: 'Email address is required.'
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // 2. Send Admin Notification Email
    sendAdminEmail({
      fullName: fullName,
      email: email,
      phone: phone,
      website: website,
      service: service,
      industry: industry,
      region: region,
      goals: goals,
      currentMarketing: currentMarketing,
      budget: budget,
      message: message,
      timestamp: timestamp
    });

    // 3. Send Auto-Reply Confirmation to Client (if enabled)
    if (CONFIG.SEND_CLIENT_AUTO_REPLY && email) {
      sendClientAutoReply({
        fullName: fullName,
        email: email,
        service: service
      });
    }

    // 4. Optionally log lead into Google Sheets
    if (CONFIG.SAVE_TO_SHEET) {
      logLeadToSheet({
        timestamp: new Date(),
        fullName: fullName,
        email: email,
        phone: phone,
        website: website,
        service: service,
        industry: industry,
        region: region,
        goals: goals,
        currentMarketing: currentMarketing,
        budget: budget,
        message: message
      });
    }

    // Return success response
    return ContentService.createTextOutput(JSON.stringify({
      status: 'success',
      message: 'Thank you! Your message has been sent successfully.',
      timestamp: timestamp
    })).setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    console.error('Error handling lead submission:', error);
    return ContentService.createTextOutput(JSON.stringify({
      status: 'error',
      message: error.toString()
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

/**
 * Handle HTTP GET requests (health check / URL test)
 */
function doGet(e) {
  return ContentService.createTextOutput(JSON.stringify({
    status: 'active',
    service: 'Pixlark Marketing Lead Intake Engine',
    recipient: CONFIG.RECIPIENT_EMAIL,
    timestamp: new Date().toISOString()
  })).setMimeType(ContentService.MimeType.JSON);
}

