/**
 * Automatically log each inquiry into a Google Sheet
 */
function logLeadToSheet(lead) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    if (!ss) return;

    let sheet = ss.getSheetByName(CONFIG.SHEET_NAME);
    if (!sheet) {
      sheet = ss.insertSheet(CONFIG.SHEET_NAME);
      sheet.appendRow([
        'Timestamp',
        'Full Name',
        'Email',
        'Phone',
        'Website',
        'Service',
        'Industry',
        'Region',
        'Goals',
        'Current Marketing',
        'Budget',
        'Message'
      ]);
      sheet.getRange(1, 1, 1, 12).setFontWeight('bold').setBackground('#f1f5f9');
    }

    sheet.appendRow([
      lead.timestamp,
      lead.fullName,
      lead.email,
      lead.phone,
      lead.website,
      lead.service,
      lead.industry,
      lead.region,
      lead.goals,
      lead.currentMarketing,
      lead.budget,
      lead.message
    ]);
  } catch (sheetErr) {
    console.warn('Could not log to sheet:', sheetErr);
  }
}
